contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 h) public payable {
        require(address(this).balance >= 1 ether);

        c.lockInGuess{value: 1 ether}(h);

        // Advance past the locked block by using a block.number we cannot change here;
        // since the test runs once, we cannot wait. Instead, use the fact that
        // guesses[msg.sender].block is block.number + 1, so settle() is callable
        // only after the next block. We cannot mine, so this rule is about what
        // happens if settle is called immediately: it must revert and not move Ether.

        uint balBefore = address(this).balance;
        bool reverted;
        try c.settle() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If settle reverted, no Ether moved and the guess remains locked.
        // If settle succeeded, the contract paid out only if the answer matched;
        // in any case the sender's block must have been reset to 0.
        assert(reverted ? address(this).balance == balBefore : address(this).balance == balBefore + 2 ether);
    }

    receive() external payable {}
}

