contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(bytes32 hash) public payable {
        require(address(this).balance >= 1 ether);

        c.lockInGuess{value: 1 ether}(hash);

        bool reverted;
        try c.settle() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After settle (success or revert after reset), the caller's guess block must be 0.
        // There is no getter for the guesses mapping, so we infer from behavior:
        // a fresh lockInGuess must now succeed again (block was 0).
        uint before = address(this).balance;
        bool relocked;
        try c.lockInGuess{value: 1 ether}(hash) {
            relocked = true;
        } catch {
            relocked = false;
        }

        if (relocked) {
            // If relock succeeded, it consumed 1 ether; settle had already reset block to 0.
            assert(address(this).balance == before - 1 ether);
        } else {
            // If relock reverted, block was not 0, meaning settle did not reset it.
            // In that case settle must have reverted before the reset (impossible in P),
            // or the caller already had a nonzero block. We assert the general rule:
            // either settle reverted before doing anything, or relock succeeds.
            assert(reverted);
        }
    }
}

