        c.lockInGuess{value: amount}(h);
        (uint beforeBlock, bytes32 beforeGuess) = c.guesses(address(this));

        require(beforeBlock != 0);

        bool reverted;
        try c.settle() {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterBlock, bytes32 afterGuess) = c.guesses(address(this));
        bytes32 answer = blockhash(beforeBlock);

        if (reverted) {
            assert(afterBlock == beforeBlock && afterGuess == beforeGuess);
        } else {
            assert(afterBlock == 0 && afterGuess == beforeGuess);
            if (beforeGuess == answer && answer != 0) {
                assert(address(this).balance == 2 ether - amount);
            } else {
                assert(address(this).balance == 0);
            }
        }
    }

    receive() external payable {}
}

